<template>
  <div class="stack_box">
    <ul class="stack_group" :aria-label="`${title} 기술 스택`">
      <li v-for="tool in visibleTools" :key="tool" class="stack_avt" :title="tool" :style="getBg(tool)">
        <span v-if="svgMap[tool]" class="svg_ico" v-html="svgMap[tool]" />
        <span v-else class="txt_ico">
          {{ getTxt(tool) }}
        </span>
      </li>
      <li v-if="restCount > 0" class="stack_avt more" :title="hiddenToolsTitle">+{{ restCount }}</li>
    </ul>
  </div>
</template>

